package com.asmj.marketplace.event.controller; import com.asmj.marketplace.common.response.ApiResponse;import com.asmj.marketplace.event.service.EventMarketplaceService;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/events") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')") public class EventAdminController{final EventMarketplaceService s;@GetMapping public ApiResponse<?> all(){return ApiResponse.ok("",s.adminEvents());}@PutMapping("/{id}/approval") public ApiResponse<?> approval(@PathVariable String id,@RequestParam boolean approved,@RequestParam(required=false) String note){return ApiResponse.ok("",s.approve(id,approved,note));}@GetMapping("/registrations") public ApiResponse<?> registrations(){return ApiResponse.ok("","Use event vendor registration endpoint for organizer monitoring");}}
